function compute(inputs) {
  const R = inputs.R;
  const C = inputs.C;
  const V0 = inputs.V0;
  const tau = R * C;
  const tMax = 5 * tau;
  const N = 100;
  const t = [];
  const V = [];
  for (let i = 0; i <= N; i++) {
    const ti = (i / N) * tMax;
    t.push(ti);
    V.push(V0 * (1 - Math.exp(-ti / tau)));
  }
  const Vtau = V0 * (1 - Math.exp(-1));
  const V5tau = V0 * (1 - Math.exp(-5));
  const series = {
    x: t,
    lines: [{ name: 'V(t)', y: V }],
    marker: { x: tau, y: Vtau }
  };
  const table = {
    columns: ['Quantity', 'Value'],
    rows: [
      ['τ = RC', tau.toFixed(6) + ' s'],
      ['V(0)', '0 V'],
      ['V(τ)', Vtau.toFixed(4) + ' V'],
      ['V(5τ)', V5tau.toFixed(4) + ' V'],
      ['V₀', V0.toFixed(2) + ' V']
    ]
  };
  const insight = `At t = τ, V = ${Vtau.toFixed(2)} V (${(100 * (1 - Math.exp(-1))).toFixed(1)}% of V₀). At t = 5τ, V = ${V5tau.toFixed(2)} V (${(100 * (1 - Math.exp(-5))).toFixed(1)}% of V₀).`;
  return {
    tau: tau,
    Vtau: Vtau,
    V5tau: V5tau,
    series: series,
    table: table,
    insight: insight
  };
}
